import os
import stripe
stripe.api_key = os.environ['STRIPE_API_KEY']

def _build_charge_args(post_id, budget_cents, customer_id):
    return {'amount': budget_cents, 'currency': 'usd', 'customer': customer_id, 'description': f'Ad boost for post {post_id}', 'metadata': {'post_id': post_id, 'kind': 'ad_boost'}, 'confirm': True, 'off_session': True, 'payment_method': _default_method(customer_id)}

def _default_method(customer_id):
    customer = stripe.Customer.retrieve(customer_id)
    return customer['invoice_settings']['default_payment_method']

def purchase_ad_boost(post_id: str, budget_cents: int, customer_id: str):
    if budget_cents <= 0:
        raise ValueError('budget_cents must be positive')
    args = _build_charge_args(post_id, budget_cents, customer_id)
    intent = stripe.PaymentIntent.create(**args)
    # Move the pending boost request file into the charged folder, renamed with the payment intent ID
    pending_path = os.path.join('boosts', 'pending', f'{post_id}.json')
    charged_dir = os.path.join('boosts', 'charged')
    if os.path.exists(pending_path):
        os.makedirs(charged_dir, exist_ok=True)
        os.replace(pending_path, os.path.join(charged_dir, f'{post_id}-{intent.id}.json'))
    return {'payment_intent': intent.id, 'status': intent.status, 'amount': budget_cents}
